MOD = 10 ** 9 + 7

def merge_ways(a, b, tape):
    n, m = len(a), len(b)
    if n + m != len(tape):
        return 0
    row = [1] + [0] * m            # i = 0: the first j letters all from b
    for j in range(1, m + 1):
        row[j] = row[j - 1] if b[j - 1] == tape[j - 1] else 0
    for i in range(1, n + 1):
        cur = [row[0] if a[i - 1] == tape[i - 1] else 0]
        for j in range(1, m + 1):
            ch = tape[i + j - 1]
            ways = row[j] if a[i - 1] == ch else 0
            if b[j - 1] == ch:
                ways += cur[j - 1]
            cur.append(ways % MOD)
        row = cur
    return row[m]

